package ru.reader.rsvp;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.Typeface;import android.net.Uri;import android.text.*;import android.view.*;import android.widget.*;import java.util.*;

public class MainActivity extends Activity {
  android.content.SharedPreferences prefs; LinearLayout root,bar; TextView wordView,progressView,speedView; ScrollView normalScroll; TextView normalText; Handler handler=new Handler(Looper.getMainLooper());
  String title="",body=""; String[] words=new String[0]; int index=0,wpm=350,display=1,size=36,bg=0xfff3e7d5,fg=0xff30221e,font=0; boolean rsvp=true,playing=false; int normalY=0; String docUri=""; String[] fontNames={"Без засечек","С засечками","Моноширинный"};
  Runnable ticker=new Runnable(){public void run(){if(!playing)return;if(rsvp){if(index<words.length-1)index++;else{playing=false;draw();return;}updateWord();}else if(normalScroll!=null){normalScroll.smoothScrollBy(0,Math.max(2,size/4));normalY=normalScroll.getScrollY();}save();handler.postDelayed(this,rsvp?Math.max(60,60000L/wpm):80);}};
  @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("reader",MODE_PRIVATE);wpm=prefs.getInt("wpm",350);display=prefs.getInt("display",1);size=prefs.getInt("size",36);bg=prefs.getInt("bg",0xfff3e7d5);fg=prefs.getInt("fg",0xff30221e);font=prefs.getInt("font",0);rsvp=prefs.getBoolean("rsvp",true);docUri=prefs.getString("uri","");index=prefs.getInt("index",0);normalY=prefs.getInt("scroll",0);draw();if(!docUri.isEmpty())load(Uri.parse(docUri),false);}
  int dp(int n){return (int)(getResources().getDisplayMetrics().density*n+.5f);} Typeface type(){return font==1?Typeface.SERIF:font==2?Typeface.MONOSPACE:Typeface.SANS_SERIF;}
  void stop(){playing=false;handler.removeCallbacks(ticker);} void save(){prefs.edit().putInt("wpm",wpm).putInt("display",display).putInt("size",size).putInt("bg",bg).putInt("fg",fg).putInt("font",font).putBoolean("rsvp",rsvp).putString("uri",docUri).putInt("index",index).putInt("scroll",normalY).apply();}
  TextView text(String s,int sp){TextView t=new TextView(this);t.setText(s);t.setTextSize(sp);t.setTextColor(fg);return t;}
  LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
  void pad(View v,int n){v.setPadding(dp(n),dp(n),dp(n),dp(n));}
  void add(LinearLayout p,View c){p.addView(c,new LinearLayout.LayoutParams(-1,-2));}
  Button button(String s,View.OnClickListener l){Button b=new Button(this);b.setAllCaps(false);b.setText(s);b.setOnClickListener(l);return b;}
  void rowButton(LinearLayout row,String s,View.OnClickListener click){Button b=button(s,click);row.addView(b,new LinearLayout.LayoutParams(0,dp(58),1));}
  void setup(){root=column();root.setBackgroundColor(bg);setContentView(root);}
  void draw(){setup();LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);add(root,top);rowButton(top,"☰",v->menu()); TextView name=text(title.isEmpty()?"Читалка RSVP":title,18);name.setSingleLine(true);name.setEllipsize(TextUtils.TruncateAt.END);top.addView(name,new LinearLayout.LayoutParams(0,-2,3));rowButton(top,"☆",v->bookmark());rowButton(top,"⚙",v->settings());
    if(words.length==0){TextView intro=text("Читалка RSVP\n\nEPUB · FB2 · HTML\n\nОткройте книгу, чтобы начать чтение.\nПоложение чтения и настройки сохраняются автоматически.",22);pad(intro,24);add(root,intro);add(root,button("Открыть книгу",v->pick()));return;}
    LinearLayout modes=new LinearLayout(this);add(root,modes);rowButton(modes,"RSVP",v->{if(!rsvp){rsvp=true;stop();save();draw();}});rowButton(modes,"Обычное чтение",v->{if(rsvp){rsvp=false;stop();save();draw();}});
    progressView=text("",13);progressView.setGravity(Gravity.CENTER);add(root,progressView);
    if(rsvp){wordView=text("",size);wordView.setGravity(Gravity.CENTER);wordView.setTypeface(type(),Typeface.BOLD);root.addView(wordView,new LinearLayout.LayoutParams(-1,0,1));updateWord();}
    else {normalScroll=new ScrollView(this);normalText=text(body,Math.max(12,(int)(size*.60)));normalText.setTypeface(type());normalText.setLineSpacing(dp(6),1.16f);pad(normalText,20);normalScroll.addView(normalText);root.addView(normalScroll,new LinearLayout.LayoutParams(-1,0,1));normalScroll.post(()->normalScroll.scrollTo(0,normalY));normalScroll.setOnScrollChangeListener((View.OnScrollChangeListener)(v,x,y,oldX,oldY)->{normalY=y;int range=Math.max(1,normalText.getHeight()-normalScroll.getHeight());index=Math.min(words.length-1,Math.round((float)y/range*(words.length-1)));updateProgress();save();});updateProgress();}
    LinearLayout controls=new LinearLayout(this);add(root,controls);rowButton(controls,"❮",v->step(-1));rowButton(controls,playing?"❚❚":"▶",v->{playing=!playing;handler.removeCallbacks(ticker);if(playing)handler.post(ticker);draw();});rowButton(controls,"❯",v->step(1));
    if(rsvp){LinearLayout speeds=new LinearLayout(this);speeds.setGravity(Gravity.CENTER_VERTICAL);add(root,speeds);speedView=text("Скорость: "+wpm+" слов/мин",15);pad(speedView,8);add(root,speedView);SeekBar seek=new SeekBar(this);seek.setMax(900);seek.setProgress(wpm-100);seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean from){wpm=p+100;speedView.setText("Скорость: "+wpm+" слов/мин");if(from)save();}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});add(root,seek);add(root,button("Показ слов: "+new String[]{"Только одно","± соседние","+ следующее"}[display],v->displayDialog()));}
    else add(root,button("Открыть другую книгу",v->pick()));
  }
  void updateProgress(){if(progressView!=null)progressView.setText((index+1)+" / "+words.length+" слов · "+((index+1)*100/Math.max(1,words.length))+"%");}
  void updateWord(){if(wordView!=null){String s=words[Math.min(index,words.length-1)];if(display==1){s=(index>0?words[index-1]+"\n":"")+s+(index+1<words.length?"\n"+words[index+1]:"");}else if(display==2&&index+1<words.length)s=s+"\n"+words[index+1];wordView.setText(s);wordView.setTextSize(size);wordView.setTypeface(type(),Typeface.BOLD);}updateProgress();}
  void step(int by){if(rsvp){index=Math.max(0,Math.min(words.length-1,index+by));updateWord();}else if(normalScroll!=null){normalScroll.smoothScrollBy(0,by*normalScroll.getHeight()*3/4);}save();}
  void menu(){String[] items={"Открыть книгу","Закладки","Настройки","Режим RSVP","Обычное чтение"};new AlertDialog.Builder(this).setItems(items,(d,n)->{if(n==0)pick();if(n==1)bookmarks();if(n==2)settings();if(n==3||n==4){stop();rsvp=n==3;save();draw();}}).show();}
  void pick(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,7);}
  @Override protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(req==7&&res==RESULT_OK&&data!=null){Uri u=data.getData();try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}load(u,true);}}
  void load(Uri uri,boolean reset){new Thread(()->{try{BookLoader.Book book=BookLoader.load(this,uri);if(book.text.isEmpty())throw new Exception("Нет текста");runOnUiThread(()->{stop();title=book.title;body=book.text;words=body.split("\\s+");docUri=uri.toString();if(reset){index=0;normalY=0;}else index=Math.max(0,Math.min(index,words.length-1));save();draw();});}catch(Exception e){runOnUiThread(()->new AlertDialog.Builder(this).setMessage("Не удалось открыть книгу: "+e.getMessage()).setPositiveButton("ОК",null).show());}}).start();}
  void bookmark(){if(words.length==0)return;String key="bookmark:"+docUri;Set<String> set=new HashSet<>(prefs.getStringSet(key,new HashSet<>()));set.add(String.valueOf(index));prefs.edit().putStringSet(key,set).apply();Toast.makeText(this,"Закладка добавлена",Toast.LENGTH_SHORT).show();}
  void bookmarks(){if(words.length==0)return;ArrayList<Integer> list=new ArrayList<>();for(String s:prefs.getStringSet("bookmark:"+docUri,new HashSet<>()))try{list.add(Integer.parseInt(s));}catch(Exception ignored){}Collections.sort(list);String[] rows=new String[list.size()];for(int i=0;i<list.size();i++){int n=list.get(i);rows[i]=(n+1)+" · "+words[Math.min(n,words.length-1)];}new AlertDialog.Builder(this).setTitle("Закладки").setItems(rows,(d,which)->{index=list.get(which);normalY=0;save();draw();}).setNeutralButton("Удалить все",(d,w)->{prefs.edit().remove("bookmark:"+docUri).apply();}).setPositiveButton("Закрыть",null).show();}
  void displayDialog(){String[] opts={"Только одно слово","Предыдущее и следующее","Текущее и следующее"};new AlertDialog.Builder(this).setTitle("Показ слов в RSVP").setSingleChoiceItems(opts,display,(d,i)->{display=i;save();d.dismiss();draw();}).setNegativeButton("Отмена",null).show();}
  void settings(){String[] options={"Режим показа слов","Шрифт","Размер шрифта","Цвет текста","Цвет фона","Тема: светлая","Тема: сепия","Тема: ночная","Тема: мягкая зелёная","Закладки","Открыть книгу"};new AlertDialog.Builder(this).setTitle("Настройки чтения").setItems(options,(d,n)->{switch(n){case 0:displayDialog();break;case 1:fontDialog();break;case 2:sizeDialog();break;case 3:colorDialog(false);break;case 4:colorDialog(true);break;case 5:theme(0xffffffff,0xff202020);break;case 6:theme(0xfff3e7d5,0xff30221e);break;case 7:theme(0xff1e2025,0xffe8e5db);break;case 8:theme(0xffdfe9d9,0xff223a29);break;case 9:bookmarks();break;case 10:pick();break;}}).show();}
  void theme(int b,int f){bg=b;fg=f;save();draw();}
  void fontDialog(){new AlertDialog.Builder(this).setTitle("Шрифт").setSingleChoiceItems(fontNames,font,(d,i)->{font=i;save();d.dismiss();draw();}).setNegativeButton("Отмена",null).show();}
  void sizeDialog(){SeekBar seek=new SeekBar(this);seek.setMax(60);seek.setProgress(size-16);new AlertDialog.Builder(this).setTitle("Размер шрифта: от 16 до 76").setView(seek).setPositiveButton("Применить",(d,w)->{size=seek.getProgress()+16;save();draw();}).setNegativeButton("Отмена",null).show();}
  void colorDialog(boolean background){LinearLayout c=column();pad(c,20);int color=background?bg:fg;String[] labels={"Красный","Зелёный","Синий"};SeekBar[] sliders=new SeekBar[3];for(int i=0;i<3;i++){add(c,text(labels[i],16));SeekBar s=new SeekBar(this);s.setMax(255);s.setProgress(i==0?Color.red(color):i==1?Color.green(color):Color.blue(color));sliders[i]=s;add(c,s);}new AlertDialog.Builder(this).setTitle(background?"Цвет фона (RGB)":"Цвет шрифта (RGB)").setView(c).setPositiveButton("Применить",(d,w)->{int n=Color.rgb(sliders[0].getProgress(),sliders[1].getProgress(),sliders[2].getProgress());if(background)bg=n;else fg=n;save();draw();}).setNegativeButton("Отмена",null).show();}
  @Override protected void onPause(){super.onPause();save();stop();} @Override protected void onDestroy(){stop();super.onDestroy();}
}
